contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v) public payable {
        require(address(c).balance >= v, "insufficient contract balance");

        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint contractBefore = address(c).balance;

        bool reverted;
        c.withdraw(v); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint contractAfter = address(c).balance;

        assert(depositsAfter == depositsBefore &&
               (reverted ? contractAfter == contractBefore
                         : contractBefore - contractAfter == v));
    }

    receive() external payable {}
}

